def page_html(lang, E, url, inline, fmt_date):
    X = TX[lang]
    ext = ' target="_blank" rel="noopener"'
    toc, cards = [], []
    for it in ITEMS:
        t = it["t"].get(lang) or it["t"]["en"]
        toc.append(f'<li><a href="#{it["id"]}">{E(t["q"])}</a></li>')
        body = []
        for b in t["a"]:
            body.append("<ul>" + "".join(f"<li>{inline(x)}</li>" for x in b) + "</ul>" if isinstance(b, list) else f"<p>{inline(b)}</p>")
        tags = " ".join(f'<span class="post-tag">{E(x)}</span>' for x in it["tags"])
        cards.append(
            f'<article class="post-card qa-item" id="{it["id"]}">'
            f'<h2><a class="qa-anchor" href="#{it["id"]}" title="{E(X["link"])}" aria-label="{E(X["link"])}">#</a> {E(t["q"])}</h2>'
            f'<p class="post-meta">{tags} · {E(X["answered"])} {E(fmt_date(it["date"], lang))}</p>'
            f'<p class="qa-ctx"><b>{E(X["q"])}:</b> {E(t["ctx"])}</p>'
            f'<div class="qa-a"><b>{E(X["a"])}:</b>{"".join(body)}</div>'
            f'<p class="refs"><a href="{FORUM}{it["forum"]}"{ext}>{E(X["forum"])} ↗</a></p></article>')
    return (f'<main class="sec blog"><div class="wrap narrow"><h1>{E(X["title"])}</h1><p class="intro">{E(X["intro"])}</p>'
            f'<p class="post-note">{E(X["note"])}</p><nav class="qa-toc"><b>{E(X["toc"])}:</b><ol>{"".join(toc)}</ol></nav>'
            f'<div class="post-list">{"".join(cards)}</div></div></main>')


def jsonld(lang, base_url, url):
    """FAQPage для поисковиков: вопрос + текст ответа без разметки."""
    import json
    import re
    strip = lambda s: re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", s).replace("`", "").replace("**", "").replace("*", "")
    ents = []
    for it in ITEMS:
        t = it["t"].get(lang) or it["t"]["en"]
        txt = " ".join(" ".join(strip(x) for x in b) if isinstance(b, list) else strip(b) for b in t["a"])
        ents.append({"@type": "Question", "name": t["q"], "url": base_url + url(lang, SLUG) + "#" + it["id"],
                     "acceptedAnswer": {"@type": "Answer", "text": txt}})
    return ('<script type="application/ld+json">'
            + json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": ents}, ensure_ascii=False).replace("</", "<\\/")
            + "</script>")
